import React, { useEffect, useId, useMemo, useRef, useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { FiSearch } from 'react-icons/fi';
import client from './client';
import { useWorkspaceList } from './hooks';
import { loadWorkspaces, rememberSelection } from './store';
import { SERVICES, serviceIds, serviceName } from './services';

// Search in the console bar: workspaces and projects, filtered here over what the API already returns.
// Projects are read once per workspace, the first time the field is used.
const MAX_RESULTS = 8;

export function searchEntries(workspaces, details) {
  const entries = workspaces.map((workspace) => ({
    key: `w:${workspace.id}`, kind: 'Workspace', name: workspace.name, hint: workspace.role || '',
    to: `/workspaces/${encodeURIComponent(workspace.id)}`, workspace,
  }));
  workspaces.forEach((workspace) => {
    (details[workspace.id]?.projects || []).forEach((project) => {
      const services = serviceIds(project.services);
      const first = SERVICES.find((service) => services.includes(service.id));
      entries.push({
        key: `p:${workspace.id}:${project.id}`, kind: 'Project', name: project.name,
        hint: `${workspace.name}${services.length ? ` · ${services.map(serviceName).join(', ')}` : ''}`,
        to: first ? first.open(workspace.id, project.id) : `/workspaces/${encodeURIComponent(workspace.id)}`,
        workspace, projectId: project.id,
      });
    });
  });
  return entries;
}

export const filterEntries = (entries, query) => {
  const words = query.trim().toLowerCase().split(/\s+/).filter(Boolean);
  if (!words.length) return [];
  return entries
    .filter((entry) => words.every((word) => `${entry.name} ${entry.hint}`.toLowerCase().includes(word)))
    .sort((a, b) => Number(b.name.toLowerCase().startsWith(words[0])) - Number(a.name.toLowerCase().startsWith(words[0])))
    .slice(0, MAX_RESULTS);
};

export default function ConsoleSearch() {
  const navigate = useNavigate();
  const { items } = useWorkspaceList({ load: false });
  const [query, setQuery] = useState('');
  const [open, setOpen] = useState(false);
  const [active, setActive] = useState(0);
  const [details, setDetails] = useState({});
  const asked = useRef(false);
  const root = useRef(null);
  const listId = useId();

  // Nothing is requested until the field is used.
  const ensureDetails = async () => {
    if (asked.current) return;
    asked.current = true;
    const snapshot = await loadWorkspaces();
    if (!snapshot.items.length) { asked.current = false; return; }
    snapshot.items.forEach((workspace) => {
      client.getWorkspace(workspace.id)
        .then((detail) => setDetails((current) => ({ ...current, [workspace.id]: detail })))
        .catch(() => { /* that workspace's projects are simply not searchable */ });
    });
  };
  useEffect(() => {
    if (!open) return undefined;
    const onPointer = (event) => { if (!root.current?.contains(event.target)) setOpen(false); };
    document.addEventListener('mousedown', onPointer);
    return () => document.removeEventListener('mousedown', onPointer);
  }, [open]);

  const entries = useMemo(() => searchEntries(items, details), [items, details]);
  const results = useMemo(() => filterEntries(entries, query), [entries, query]);
  const showing = open && query.trim().length > 0;

  const choose = (entry) => {
    rememberSelection({ workspaceId: entry.workspace.id, workspaceName: entry.workspace.name, projectId: entry.projectId || null });
    setOpen(false); setQuery('');
    navigate(entry.to);
  };
  const onKeyDown = (event) => {
    if (event.key === 'Escape') { setOpen(false); return; }
    if (!showing || !results.length) return;
    if (event.key === 'ArrowDown') { event.preventDefault(); setActive((active + 1) % results.length); }
    if (event.key === 'ArrowUp') { event.preventDefault(); setActive((active + results.length - 1) % results.length); }
    if (event.key === 'Enter') { event.preventDefault(); choose(results[Math.min(active, results.length - 1)]); }
  };

  return (
    <div className="cs-search" ref={root} role="search" onBlur={(event) => { if (!root.current?.contains(event.relatedTarget)) setOpen(false); }}>
      <FiSearch aria-hidden="true" />
      <input
        type="search"
        value={query}
        placeholder="Search workspaces and projects"
        aria-label="Search workspaces and projects"
        role="combobox"
        aria-expanded={showing}
        aria-controls={showing ? listId : undefined}
        aria-activedescendant={showing && results.length ? `${listId}-${Math.min(active, results.length - 1)}` : undefined}
        autoComplete="off"
        onFocus={() => { setOpen(true); ensureDetails(); }}
        onChange={(event) => { setQuery(event.target.value); setActive(0); setOpen(true); ensureDetails(); }}
        onKeyDown={onKeyDown}
      />
      {showing && (
        <ul id={listId} className="cs-search__pop" role="listbox" aria-label="Search results">
          {results.length === 0 && <li className="cs-search__none" role="presentation">No match</li>}
          {results.map((entry, index) => (
            <li
              key={entry.key}
              id={`${listId}-${index}`}
              role="option"
              aria-selected={index === active}
              onMouseEnter={() => setActive(index)}
              onMouseDown={(event) => { event.preventDefault(); choose(entry); }}
            >
              <span translate="no">{entry.name}</span>
              <small>{entry.kind}{entry.hint ? ` · ${entry.hint}` : ''}</small>
            </li>
          ))}
        </ul>
      )}
    </div>
  );
}
